    self->x = (self->x + self->vx);
    self->y = (self->y + self->vy);
        if ((self->y > ((DashFixed)(LONG)(SUELO) << 16))) {
        self->y = ((DashFixed)(LONG)(SUELO) << 16);
        self->vy = _dash_fx_mul((-self->vy), ((DashFixed)55706));
        }
        if (((self->x < ((DashFixed)524288)) || (self->x > ((DashFixed)19660800)))) {
        self->vx = (-self->vx);
        }
}
